class Solution:
    def rotate(self, pin: str, pos: int, direction: int) -> str:
        rotation = str((int(pin[pos]) + direction) % 10)
        pin = list(pin)
        pin[pos] = rotation
        return ''.join(pin)

    def openLock(self, deadends: List[str], target: str) -> int:
        init = '0000'
        deadends = set(deadends)
        if init in deadends:
            return -1
        queue = collections.deque([init])

        dis = 0
        seen = set(queue)
        while queue:
            n = len(queue)
            if target in seen:
                return dis
            dis += 1
            for _ in range(n):
                lock = queue.popleft()
                for i in range(8):
                    direction = 1 if i < 4 else -1
                    rotation = self.rotate(lock, i % 4, direction)
                    if rotation not in deadends and rotation not in seen:
                        queue.append(rotation)
                        seen.add(rotation)
        return -1
